<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/safety_vote_phase5.php';
function sv5_campaign(int$id):?array{return db_row('SELECT c.*,v.CampaignType,v.PrivacyMode,v.TitleTh,v.PrivacyThreshold,v.ResultVisibility,v.Status VersionStatus FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.id=?',[$id]);}
function sv5_counts(array$c):array{$x=db_row("SELECT (SELECT EligibleCount FROM SafetyVote_EligibilitySnapshots WHERE CampaignVersionID=? AND Status='frozen' ORDER BY id DESC LIMIT 1) eligible,(SELECT COUNT(*) FROM SafetyVote_Participation WHERE CampaignVersionID=? AND State IN ('started','submitted')) started,(SELECT COUNT(*) FROM SafetyVote_Participation WHERE CampaignVersionID=? AND State='submitted') submitted,(SELECT COUNT(*) FROM SafetyVote_Ballots WHERE CampaignVersionID=? AND Status='Accepted') accepted",[$c['CurrentVersionID'],$c['CurrentVersionID'],$c['CurrentVersionID'],$c['CurrentVersionID']]);return array_map('intval',$x?:[]);}
function sv5_recipients(array$c,string$audience):?array{if(!in_array($audience,['eligible','nonparticipants'],true))return null;$sql="SELECT ev.EmployeeID FROM SafetyVote_EligibleVoters ev JOIN SafetyVote_EligibilitySnapshots es ON es.id=ev.SnapshotID WHERE es.CampaignVersionID=? AND es.Status='frozen'";if($audience==='nonparticipants')$sql.=" AND NOT EXISTS(SELECT 1 FROM SafetyVote_Participation p WHERE p.CampaignVersionID=es.CampaignVersionID AND p.EmployeeID=ev.EmployeeID AND p.State='submitted')";return db_rows($sql.' ORDER BY ev.EmployeeID',[$c['CurrentVersionID']]);}
function sv5_report_dir():string{$d=dirname(__DIR__).DIRECTORY_SEPARATOR.'private'.DIRECTORY_SEPARATOR.'safety-vote'.DIRECTORY_SEPARATOR.'reports';if(!is_dir($d)&&!mkdir($d,0770,true)&&!is_dir($d))throw new RuntimeException('report directory');return$d;}
function sv5_csv(array$m):string{$q=fn($v)=>'"'.str_replace('"','""',(string)$v).'"';$rows=[['Report ID',$m['reportId']],['Campaign',$m['campaignCode']],['Title',$m['title']],['Snapshot',$m['snapshotNo']],['Result SHA-256',$m['resultHash']],[],['Rank','Label','Metric','Value','State']];foreach($m['rows']as$x)$rows[]=[$x['rank'],$x['label'],$x['metric'],$x['value'],$x['state']];return"\xEF\xBB\xBF".implode("\r\n",array_map(fn($r)=>implode(',',array_map($q,$r)),$rows));}
function sv5_pdf(array$m):string{$esc=fn($s)=>preg_replace('/[^\x20-\x7e]/','?',str_replace(['\\','(',')'],['\\\\','\\(','\\)'],(string)$s));$lines=['Safety Vote Certified Report '.$m['reportId'],$m['campaignCode'].' - '.$m['title'],'Snapshot '.$m['snapshotNo'],'Result SHA-256 '.$m['resultHash']];foreach($m['rows']as$x)$lines[]=($x['rank']?:'-').' '.$x['label'].' '.$x['metric'].' '.($x['value']??'-').' '.$x['state'];$parts=[];foreach($lines as$i=>$x)$parts[]=($i?'0 -16 Td ':'').'('.$esc($x).') Tj';$stream='BT /F1 10 Tf 40 790 Td '.implode(' ',$parts).' ET';$objs=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>','<< /Length '.strlen($stream)." >>\nstream\n$stream\nendstream",'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];$out="%PDF-1.4\n";$off=[0];foreach($objs as$i=>$o){$off[$i+1]=strlen($out);$out.=($i+1)." 0 obj\n$o\nendobj\n";}$xref=strlen($out);$out.='xref'."\n0 ".(count($objs)+1)."\n0000000000 65535 f \n";foreach(array_slice($off,1)as$x)$out.=str_pad((string)$x,10,'0',STR_PAD_LEFT)." 00000 n \n";return$out.'trailer << /Size '.(count($objs)+1).' /Root 1 0 R >>'."\nstartxref\n$xref\n%%EOF";}
function sv5_create_report(array$u,array$c,array$snap,string$format,string$type):array{$pdo=db();$pdo->beginTransaction();$file=null;try{$q=$pdo->prepare('SELECT * FROM SafetyVote_ResultSnapshots WHERE id=? AND CampaignID=? FOR UPDATE');$q->execute([$snap['id'],$c['id']]);$locked=$q->fetch();if(!$locked)throw new RuntimeException('RESULT_NOT_FOUND');$q=$pdo->prepare('SELECT COALESCE(MAX(ReportVersion),0)+1 version FROM SafetyVote_Reports WHERE ResultSnapshotID=? AND ReportType=?');$rt=$type.'_'.$format;$q->execute([$snap['id'],$rt]);$version=(int)$q->fetch()['version'];$reportId='SV-'.$c['id'].'-'.$snap['id'].'-'.strtoupper($type).'-'.strtoupper($format).'-V'.$version;$q=$pdo->prepare("SELECT rr.RankNo rank,COALESCE(ca.CandidateNo,o.Label,CONCAT('Row ',rr.id)) label,rr.MetricKey metric,COALESCE(rr.NumericValue,rr.RawCount) value,rr.ResultState state FROM SafetyVote_ResultRows rr LEFT JOIN SafetyVote_Candidates ca ON ca.id=rr.CandidateID LEFT JOIN SafetyVote_Options o ON o.id=rr.OptionID WHERE rr.ResultSnapshotID=? ORDER BY rr.RankNo,rr.id");$q->execute([$snap['id']]);$generated=(new DateTimeImmutable())->format('Y-m-d\TH:i:s.000\Z');$built=sv5_report_model(['reportId'=>$reportId,'campaignCode'=>$c['CampaignCode'],'title'=>$c['TitleTh'],'resultHash'=>$locked['ResultHash'],'snapshotNo'=>$locked['SnapshotNo'],'generatedAt'=>$generated,'rows'=>$q->fetchAll()]);$content=$format==='pdf'?sv5_pdf($built['model']):sv5_csv($built['model']);$mime=$format==='pdf'?'application/pdf':'application/vnd.ms-excel';$stored=$reportId.'-'.bin2hex(random_bytes(8)).'.'.($format==='pdf'?'pdf':'csv');$file=sv5_report_dir().DIRECTORY_SEPARATOR.$stored;file_put_contents($file,$content);$sha=hash('sha256',$content);$q=$pdo->prepare('INSERT INTO SafetyVote_Reports(ResultSnapshotID,ReportType,ReportID,ReportVersion,StoredName,MimeType,FileSize,ContentSha256,ResultHashSnapshot,GeneratedBy) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$snap['id'],$rt,$reportId,$version,$stored,$mime,strlen($content),$sha,$locked['ResultHash'],sv_actor($u)]);$id=(int)$pdo->lastInsertId();$pdo->commit();return['id'=>$id,'reportId'=>$reportId,'format'=>$format,'mimeType'=>$mime,'fileSize'=>strlen($content),'contentSha256'=>$sha,'resultHash'=>$locked['ResultHash'],'modelHash'=>$built['modelHash']];}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();if($file&&is_file($file))@unlink($file);throw$e;}}
function handle_safety_vote_phase5_routes(string$method,string$path):bool{if(strpos($path,'/safety-vote/')!==0)return false;$u=require_user();if($method==='GET'&&$path==='/safety-vote/notifications'){sv_require_schema();sv_require_permission($u,'SAFETY_VOTE_VIEW');$rows=db_rows("SELECT id,CampaignID,EventType,TemplateKey,Channel,DispatchedAt,PayloadMetadataJson FROM SafetyVote_Notifications WHERE RecipientEmployeeID=? AND Status='Sent' ORDER BY DispatchedAt DESC LIMIT 100",[sv_actor($u)]);foreach($rows as&$x){$x['metadata']=json_decode((string)$x['PayloadMetadataJson'],true)?:[];unset($x['PayloadMetadataJson']);}unset($x);json_response(['success'=>true,'data'=>['rows'=>$rows]]);}$ops=route_params($path,'/safety-vote/admin/campaigns/:id/operations');$org=route_params($path,'/safety-vote/admin/campaigns/:id/analytics/organization');$preview=route_params($path,'/safety-vote/admin/campaigns/:id/notifications/preview');$queue=route_params($path,'/safety-vote/admin/campaigns/:id/notifications/queue');$retry=route_params($path,'/safety-vote/admin/notifications/:id/retry');$exports=route_params($path,'/safety-vote/admin/campaigns/:id/exports');$cert=route_params($path,'/safety-vote/admin/campaigns/:id/exports/certified-report');$file=route_params($path,'/safety-vote/admin/campaigns/:id/reports/:reportId/file');$audit=route_params($path,'/safety-vote/admin/campaigns/:id/audit');$process=$path==='/safety-vote/admin/operations/process-due';$dispatch=$path==='/safety-vote/admin/notifications/dispatch';$retention=$path==='/safety-vote/admin/retention/preview';if(!$ops&&!$org&&!$preview&&!$queue&&!$retry&&!$exports&&!$cert&&!$file&&!$audit&&!$process&&!$dispatch&&!$retention)return false;sv_require_schema();
 if($ops&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_RESULT_VIEW');$c=sv5_campaign((int)$ops['id']);if(!$c)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND'],404);$n=sv5_counts($c);$f=sv5_funnel($n+['threshold'=>$c['PrivacyThreshold'],'privacyMode'=>$c['PrivacyMode']]);json_response(['success'=>true,'data'=>['campaign'=>['id'=>(int)$c['id'],'status'=>$c['Status'],'scheduledOpenAt'=>$c['ScheduledOpenAt'],'scheduledCloseAt'=>$c['ScheduledCloseAt'],'timeZone'=>'Asia/Bangkok'],'funnel'=>$f,'timeline'=>db_rows('SELECT Action,TargetType,TargetID,StatusCode,BoundedDetail,OccurredAt FROM SafetyVote_AuditLogs WHERE CampaignID=? ORDER BY id DESC LIMIT 100',[$c['id']]),'notifications'=>db_rows('SELECT Status,COUNT(*) total FROM SafetyVote_Notifications WHERE CampaignID=? GROUP BY Status',[$c['id']]),'exports'=>db_rows('SELECT Status,COUNT(*) total FROM SafetyVote_ExportJobs WHERE CampaignID=? GROUP BY Status',[$c['id']]),'health'=>['reconciliation'=>$f['reconciliation'],'privacySuppression'=>true]]]);}
 if($org&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_RESULT_VIEW');$c=sv5_campaign((int)$org['id']);if(!$c)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND'],404);if($c['PrivacyMode']==='secret_ballot')json_response(['success'=>false,'code'=>'SECRET_DIMENSION_FORBIDDEN'],403);$rows=db_rows("SELECT COALESCE(NULLIF(e.Department,''),'Unresolved') dimension,COUNT(*) total FROM SafetyVote_Participation p JOIN Employees e ON e.EmployeeID=p.EmployeeID WHERE p.CampaignVersionID=? AND p.State='submitted' GROUP BY e.Department ORDER BY e.Department",[$c['CurrentVersionID']]);foreach($rows as&$x)$x=['dimension'=>$x['dimension']]+sv5_suppress($x['total'],$c['PrivacyThreshold'],$c['PrivacyMode'],'department');unset($x);json_response(['success'=>true,'data'=>['rows'=>$rows]]);}
 if($process&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$rows=db_rows("SELECT * FROM SafetyVote_Campaigns WHERE Status IN ('Draft','Open') AND ((Status='Draft' AND ScheduledOpenAt IS NOT NULL AND ScheduledOpenAt<=CONVERT_TZ(UTC_TIMESTAMP(),'+00:00','+07:00')) OR (Status='Open' AND ScheduledCloseAt IS NOT NULL AND ScheduledCloseAt<=CONVERT_TZ(UTC_TIMESTAMP(),'+00:00','+07:00'))) FOR UPDATE");$changed=[];foreach($rows as$c){$action=$c['Status']==='Draft'?'open':'close';$to=$action==='open'?'Open':'Closed';db_execute("UPDATE SafetyVote_Campaigns SET Status=?,OpenedAt=IF(?='Open',NOW(),OpenedAt),ClosedAt=IF(?='Closed',NOW(),ClosedAt),UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=? AND Status=?",[$to,$to,$to,sv_actor($u),$c['id'],$c['Status']]);db_execute('UPDATE SafetyVote_CampaignVersions SET Status=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?',[$to,sv_actor($u),$c['CurrentVersionID']]);sv_audit($u,'SAFETY_VOTE_SCHEDULE_'.strtoupper($action),'SafetyVote_Campaign',(string)$c['id'],'Asia/Bangkok',[],$c['id'],$c['CurrentVersionID']);$changed[]=['id'=>(int)$c['id'],'action'=>$action,'status'=>$to];}json_response(['success'=>true,'data'=>['timeZone'=>'Asia/Bangkok','processedAt'=>(new DateTimeImmutable())->format(DATE_ATOM),'changed'=>$changed]]);}
 if($preview&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$c=sv5_campaign((int)$preview['id']);$aud=(string)($_GET['audience']??'nonparticipants');$rows=$c?sv5_recipients($c,$aud):null;if(!$c)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND'],404);if($rows===null)json_response(['success'=>false,'code'=>'AUDIENCE_INVALID'],400);json_response(['success'=>true,'data'=>['audience'=>$aud,'total'=>count($rows),'rows'=>array_map(fn($x)=>['employeeId'=>$x['EmployeeID']],array_slice($rows,0,100)),'truncated'=>count($rows)>100]]);}
 if($queue&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$c=sv5_campaign((int)$queue['id']);$b=json_body();$aud=(string)($b['audience']??'nonparticipants');$rows=$c?sv5_recipients($c,$aud):null;if(!$c||$rows===null)json_response(['success'=>false,'code'=>$c?'AUDIENCE_INVALID':'CAMPAIGN_NOT_FOUND'],400);$event=sv3_text($b['eventType']??'reminder',50);$template=sv3_text($b['templateKey']??'vote_reminder',80);$channel=in_array($b['channel']??'in_app',['in_app','email'],true)?$b['channel']:'in_app';$scheduled=$b['scheduledAt']??date('Y-m-d H:i:s');$window=(string)($b['windowKey']??substr($scheduled,0,10));$meta=sv5_safe_metadata($b['metadata']??[]);$queued=0;$suppressed=0;foreach($rows as$x){$key=sv5_notification_key(['campaignId'=>$c['id'],'eventType'=>$event,'channel'=>$channel,'recipientEmployeeId'=>$x['EmployeeID'],'windowKey'=>$window]);$n=db_execute('INSERT IGNORE INTO SafetyVote_Notifications(CampaignID,EventType,TemplateKey,Channel,RecipientEmployeeID,ScheduledAt,SuppressionKey,PayloadMetadataJson,CreatedBy) VALUES(?,?,?,?,?,?,?,?,?)',[$c['id'],$event,$template,$channel,$x['EmployeeID'],$scheduled,$key,json_encode($meta),sv_actor($u)]);$n?$queued++:$suppressed++;}sv_audit($u,'SAFETY_VOTE_NOTIFICATION_QUEUE','SafetyVote_Campaign',(string)$c['id'],'queued='.$queued.'; suppressed='.$suppressed,['eventType'=>$event,'channel'=>$channel,'audience'=>$aud],$c['id'],$c['CurrentVersionID']);json_response(['success'=>true,'data'=>['queued'=>$queued,'suppressed'=>$suppressed,'total'=>count($rows)]],201);}
 if($dispatch&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');if((string)getenv('SAFETY_VOTE_NOTIFICATION_TRANSPORT')!=='fixture')json_response(['success'=>false,'code'=>'NOTIFICATION_TRANSPORT_UNAVAILABLE'],503);$limit=min(100,max(1,(int)(json_body()['limit']??25)));$rows=db_rows("SELECT * FROM SafetyVote_Notifications WHERE Status IN ('Queued','Retry') AND AttemptCount<MaxAttempts AND ScheduledAt<=NOW() AND (NextAttemptAt IS NULL OR NextAttemptAt<=NOW()) ORDER BY id LIMIT $limit");$sent=0;$failed=0;foreach($rows as$n){$employee=db_row('SELECT CompanyEmail FROM Employees WHERE EmployeeID=?',[$n['RecipientEmployeeID']]);$attempt=(int)$n['AttemptCount']+1;$ok=$n['Channel']==='in_app'||!empty($employee['CompanyEmail']);$code=$ok?null:'RECIPIENT_CHANNEL_UNAVAILABLE';db_execute('INSERT INTO SafetyVote_NotificationDeliveries(NotificationID,AttemptNo,DeliveryState,ErrorCode,MetadataJson) VALUES(?,?,?,?,?)',[$n['id'],$attempt,$ok?'Sent':'Failed',$code,json_encode(['channel'=>$n['Channel'],'transport'=>'fixture'])]);db_execute("UPDATE SafetyVote_Notifications SET Status=?,AttemptCount=?,LastErrorCode=?,DispatchedAt=IF(?='Sent',NOW(),DispatchedAt),NextAttemptAt=IF(?='Failed',DATE_ADD(NOW(),INTERVAL 5 MINUTE),NULL) WHERE id=?",[$ok?'Sent':'Failed',$attempt,$code,$ok?'Sent':'Failed',$ok?'Sent':'Failed',$n['id']]);$ok?$sent++:$failed++;}json_response(['success'=>true,'data'=>['processed'=>count($rows),'sent'=>$sent,'failed'=>$failed,'externalDelivery'=>false,'transport'=>'fixture']]);}
 if($retry&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$n=db_execute("UPDATE SafetyVote_Notifications SET Status='Retry',NextAttemptAt=NOW(),LastErrorCode=NULL WHERE id=? AND Status='Failed' AND AttemptCount<MaxAttempts",[(int)$retry['id']]);if(!$n)json_response(['success'=>false,'code'=>'NOTIFICATION_RETRY_REJECTED'],409);json_response(['success'=>true,'data'=>['id'=>(int)$retry['id'],'status'=>'Retry']]);}
 if($exports&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_EXPORT');$c=sv5_campaign((int)$exports['id']);$b=json_body();$format=in_array($b['format']??'excel',['excel','pdf'],true)?$b['format']:'excel';$sid=(int)($b['snapshotId']??0);$snap=$c?db_row("SELECT * FROM SafetyVote_ResultSnapshots WHERE id=? AND CampaignID=? AND Status IN ('Frozen','Certified','Published')",[$sid,$c['id']]):null;if(!$snap)json_response(['success'=>false,'code'=>'RESULT_STATE_CONFLICT'],409);db_execute("INSERT INTO SafetyVote_ExportJobs(CampaignID,CampaignVersionID,ResultSnapshotID,ExportType,Format,PrivacyClass,Status,RequestedBy,StartedAt) VALUES(?,?,?,'aggregate',?,'aggregate','Running',?,NOW())",[$c['id'],$c['CurrentVersionID'],$sid,$format,sv_actor($u)]);$job=(int)db()->lastInsertId();try{$report=sv5_create_report($u,$c,$snap,$format,'aggregate');db_execute("UPDATE SafetyVote_ExportJobs SET Status='Completed',CompletedAt=NOW(),ReportID=? WHERE id=?",[$report['id'],$job]);sv_audit($u,'SAFETY_VOTE_EXPORT_COMPLETE','SafetyVote_ExportJob',(string)$job,'format='.$format,['reportId'=>$report['reportId'],'sha256'=>$report['contentSha256']],$c['id'],$c['CurrentVersionID']);json_response(['success'=>true,'data'=>['jobId'=>$job,'status'=>'Completed','report'=>$report]],201);}catch(Throwable$e){db_execute("UPDATE SafetyVote_ExportJobs SET Status='Failed',CompletedAt=NOW(),ErrorCode='EXPORT_FAILED' WHERE id=?",[$job]);json_response(['success'=>false,'code'=>'EXPORT_FAILED'],500);}}
 if($cert&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_EXPORT');$c=sv5_campaign((int)$cert['id']);$b=json_body();$sid=(int)($b['snapshotId']??0);$format=($b['format']??'pdf')==='excel'?'excel':'pdf';$snap=$c?db_row("SELECT * FROM SafetyVote_ResultSnapshots WHERE id=? AND CampaignID=? AND Status IN ('Certified','Published')",[$sid,$c['id']]):null;if(!$snap)json_response(['success'=>false,'code'=>'CERTIFIED_RESULT_REQUIRED'],422);$report=sv5_create_report($u,$c,$snap,$format,'certified');sv_audit($u,'SAFETY_VOTE_CERTIFIED_REPORT','SafetyVote_Report',(string)$report['id'],$report['reportId'],['resultHash'=>$report['resultHash'],'sha256'=>$report['contentSha256']],$c['id'],$c['CurrentVersionID']);json_response(['success'=>true,'data'=>$report],201);}
 if($file&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_EXPORT');$x=db_row("SELECT rp.* FROM SafetyVote_Reports rp JOIN SafetyVote_ResultSnapshots rs ON rs.id=rp.ResultSnapshotID WHERE rp.ReportID=? AND rs.CampaignID=? AND rp.Status='Ready'",[$file['reportId'],(int)$file['id']]);$disk=$x?sv5_report_dir().DIRECTORY_SEPARATOR.basename($x['StoredName']):'';if(!$x||!is_file($disk))json_response(['success'=>false,'code'=>'REPORT_NOT_FOUND'],404);if(hash_file('sha256',$disk)!==$x['ContentSha256'])json_response(['success'=>false,'code'=>'REPORT_INTEGRITY_FAILED'],409);header('Content-Type: '.$x['MimeType']);header('Content-Disposition: attachment; filename="'.$x['ReportID'].($x['MimeType']==='application/pdf'?'.pdf':'.csv').'"');header('Cache-Control: private, no-store');header('X-Content-SHA256: '.$x['ContentSha256']);readfile($disk);exit;}
 if($audit&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_AUDIT_VIEW');$rows=db_rows('SELECT id,ActorEmployeeID,ActorRole,Action,TargetType,TargetID,StatusCode,ReasonCode,BoundedDetail,MetadataJson,OccurredAt FROM SafetyVote_AuditLogs WHERE CampaignID=? ORDER BY id DESC LIMIT 500',[(int)$audit['id']]);foreach($rows as&$x){$x['metadata']=json_decode((string)$x['MetadataJson'],true)?:[];unset($x['MetadataJson']);}unset($x);json_response(['success'=>true,'data'=>['classification'=>'restricted_audit','rows'=>$rows]]);}
 if($retention&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_ADMIN');$x=db_row("SELECT SettingValue FROM SafetyVote_Settings WHERE SettingKey='retention_days'");$days=max(30,(int)($x['SettingValue']??2555));$rows=db_rows("SELECT id,RequestedAt createdAt,Status status FROM SafetyVote_ExportJobs WHERE RequestedAt<DATE_SUB(NOW(),INTERVAL $days DAY)");json_response(['success'=>true,'data'=>sv5_retention($rows,$days)]);}
 return false;}
